-- Fiche Les animaux (CP) - anglais, notion 'en_animaux'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cp', 'english', 'Les animaux', $fiche$
[titre]Un, une : a[/titre]
[cadre]un chat = [b]a[/b] cat · une vache = [b]a[/b] cow
